self::cached($cache, '__category_summary', $refresh, static function (): array {
            $items = [];
            foreach (self::query()->all() as $category) {
                $items[$category->id] = [
                    'name' => $category->name,
                    'desc' => $category->desc,
                    'url' => null, // 阶段 E 由 UrlGenerator 生成（route category/show）
                    'postCount' => $category->getPostCount(),
                ];
            }
            return $items;
        })

MixedReturnStatement.code:
$cache->getOrSet(
            $key,
            static function () use ($urlGenerator, $aliases, $limit, $size): array {
                $items = [];
                $comments = self::query()
                    ->orderBy(['create_time' => SORT_DESC])
                    ->limit($limit)
                    ->all();
                foreach ($comments as $comment) {
                    $post = $comment->getPost();
                    $items[] = [
                        'id' => $comment->id,
                        'nickname' => $comment->nickname,
                        'website' => $comment->url,
                        'pid' => $comment->pid,
                        'post_url' => $post?->getUrl($urlGenerator) . '#comment-' . $comment->id,
                        'content' => $comment->content,
                        'create_time' => $comment->create_time,
                        'email' => $comment->email,
                        'avatar' => XUtils::getAvatar($aliases, $comment->email, $size),
                        'title' => $post?->title ?? '',
                    ];
                }
                return $items;
            },
            3600,
            new CallbackDependency(
                static fn (): int => (int)self::query()->max('update_time'),
            ),
        )

$cache->getOrSet(
            '__nav_tree',
            static function (): array {
                $items = [];
                foreach (self::query()->where(['pid' => 0])->orderBy(['sort_order' => SORT_DESC])->all() as $node) {
                    $children = [];
                    foreach ($node->getChildren()->all() as $child) {
                        $children[] = [
                            'label' => $child->name,
                            'url' => $child->getUrl(),
                        ];
                    }
                    $items[$node->id] = [
                        'label' => $node->name,
                        'url' => $node->getUrl(),
                        'items' => $children,
                    ];
                }
                return $items;
            },
            3600,
            new CallbackDependency(
                static fn(): int => (int)self::query()->max('update_time'),
            ),
        )

$cache->getOrSet(
            '__parent_nav',
            static function (): array {
                $items = [];
                foreach (self::query()->select('id,name')->where(['pid' => 0])->orderBy(['sort_order' => SORT_DESC])->asArray()->all() as $row) {
                    $items[(int)$row['id']] = (string)$row['name'];
                }
                return $items;
            },
            3600,
            new CallbackDependency(
                static fn(): int => (int)self::query()->max('update_time'),
            ),
        )

$cache->getOrSet(
            $key,
            function () use ($relation, $category, $simple): ?self {
                $query = self::query()
                    ->where(['in', 'status', self::visibleStatuses()])
                    ->andWhere(['!=', 'id', $this->id]);
                if ($category) {
                    $query->andWhere(['cid' => $this->cid]);
                }
                if ($relation === 'before') {
                    $query->andWhere(['<=', 'post_time', (int)$this->post_time])
                        ->orderBy(['post_time' => SORT_DESC]);
                } else {
                    $query->andWhere(['>=', 'post_time', (int)$this->post_time])
                        ->orderBy(['post_time' => SORT_ASC]);
                }
                if ($simple) {
                    $query->select('id,title,alias,status');
                }
                return $query->one();
            },
            3600,
            new CallbackDependency(
                static fn (): int => (int)self::query()->max('update_time'),
            ),
        )

$cache->getOrSet(
            $key,
            static function () use ($urlGenerator, $limit): array {
                $query = self::query()
                    ->select('name, COUNT(*) as totalCount, MAX(create_time) as create_time')
                    ->groupBy('name')
                    ->orderBy(['totalCount' => SORT_DESC]);
                if ($limit > 0) {
                    $query->limit($limit);
                }
                $items = [];
                foreach ($query->asArray()->all() as $row) {
                    $name = (string)$row['name'];
                    $items[] = [
                        'totalCount' => (int)$row['totalCount'],
                        'name' => $name,
                        'create_time' => (int)$row['create_time'],
                        'url' => self::getUrl($urlGenerator, $name),
                    ];
                }
                return $items;
            },
            3600,
            new CallbackDependency(
                static fn (): int => (int)self::query()->max('id'),
            ),
        )
